class Solution {
  private static boolean isPrime(long x) {
    if (x < 2) return false;
    for (long d = 2; d * d <= x; d++) if (x % d == 0) return false;
    return true;
  }

  public long sumOfLargestPrimes(String s) {
    java.util.TreeSet<Long> primes = new java.util.TreeSet<>();
    int n = s.length();
    for (int i = 0; i < n; i++) {
      long v = 0;
      for (int j = i; j < n; j++) {
        v = v * 10 + s.charAt(j) - '0';
        if (isPrime(v)) primes.add(v);
      }
    }
    long sum = 0;
    for (int t = 0; t < 3 && !primes.isEmpty(); t++) sum += primes.pollLast();
    return sum;
  }
}
